&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Lead and execute global CMC regulatory strategies for assigned programs across all phases of development, including IND, IMPD, BLA/MAA, and post-approval lifecycle management&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
