&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Provide strategic regulatory guidance to Manufacturing and Quality organizations to ensure global compliance and readiness for clinical and commercial supply&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
